let cached_rate = null

async function btc_usd_rate(from = 'btc', to = 'usd') {
  if (cached_rate) return cached_rate

  const fromSymbol = (from || 'btc').toLowerCase()
  const toSymbol = (to || 'usd').toLowerCase()

  // 1. Try Coinbase Spot Price API
  try {
    const response = await fetch(`https://api.coinbase.com/v2/prices/${fromSymbol.toUpperCase()}-${toSymbol.toUpperCase()}/spot`)
    if (response.ok) {
      const data = await response.json()
      const rate = Number(data?.data?.amount)
      if (!isNaN(rate) && rate > 0) {
        cached_rate = rate
        return cached_rate
      }
    }
  } catch (err) {
    console.warn('[btc_usd_rate] Coinbase fetch failed:', err.message || err)
  }

  // 2. Try Blockchain.info Ticker API as Fallback
  try {
    if (fromSymbol === 'btc') {
      const response = await fetch('https://blockchain.info/ticker')
      if (response.ok) {
        const data = await response.json()
        const fiatKey = toSymbol.toUpperCase()
        const rate = Number(data?.[fiatKey]?.last)
        if (!isNaN(rate) && rate > 0) {
          cached_rate = rate
          return cached_rate
        }
      }
    }
  } catch (err) {
    console.warn('[btc_usd_rate] Blockchain.info fetch failed:', err.message || err)
  }

  // 3. Fallback to cached rate or a default baseline rate (60000.0) to prevent 0 / crash
  return cached_rate || 60000.0
}

module.exports = btc_usd_rate